private void ExportExcel_DanhGia()
{
    Hashtable hstColumns = new Hashtable();
    Hashtable hstReplaceValues = new Hashtable();
    SIM_Branch obj = new SIM_Branch();

    try
    {
        bool? bolDinhChi = null;
        if (rdoStatus1.Checked)
            bolDinhChi = false;
        else if (rdoStatus2.Checked)
            bolDinhChi = true;

        DataTable dtbExport = obj.GetDataTable("SIM_SubjectMark_Search_SubjectMarkDetail",
                                    "@ClassID", uClass.ClassID,
                                    "@DinhChi", bolDinhChi,
                                    "@YearID", uYearSemester.YearID,
                                    "@Semester", uYearSemester.Semester,
                                    "@IsFirst", chkIsFirst.Checked);
        if (dtbExport == null)
        {
            lblMsg.Text = "Việc lấy thông tin bị lỗi!";
            lblMsg.Visible = true;
            return;
        }

        string strPath = System.Web.HttpContext.Current.Server.MapPath("~");
        string strFilePath = strPath + "Template\\Tong hop danh gia.xls";

        string strFileNameSaveAs = "Tong hop danh gia - " + User.UserName + ".xls";
        string strPathSaveAs = strPath + "Export\\" + strFileNameSaveAs;

        string strTitle = "";
        if (uYearSemester.YearID == null && uYearSemester.Semester == null)
            strTitle = "TỔNG HỢP ĐÁNH GIÁ CUỐI KHÓA";
        else
        {
            if (uYearSemester.Semester == null)
                strTitle = "TỔNG HỢP ĐÁNH GIÁ CUỐI NĂM HỌC " + uYearSemester.YearText;
            else
                strTitle = "TỔNG HỢP ĐÁNH NĂM HỌC " + uYearSemester.YearText + " HỌC KÌ " + uYearSemester.Semester;
        }
        hstReplaceValues.Add("{Title}", strTitle);

        string[] cols = { "StudentCode", "StudentFirstName", "StudentLastName", "OffQuantityTotal", "CP_OffQuantityTotal", "KP_OffQuantityTotal", "SummaryLearningMark", "EthicLevel", "DebtSubjectCount", "Description" };

        foreach (string str in cols)
            hstColumns.Add(str, str);

        if (Libs.CExcel.ExportTemplateExcel(dtbExport, strFilePath, "StudentCode", hstColumns, hstReplaceValues, strPathSaveAs))
        {
            Response.Redirect("/Export/" + strFileNameSaveAs);
        }
        else
        {
            lblMsg.Text = "Việc xuất excel thất bại!";
            lblMsg.Visible = true;
        }
    }
    catch (Exception ex)
    {
        lblMsg.Text = "Lỗi xuất Excel đánh giá: " + ex.Message;
        lblMsg.Visible = true;
    }
}

